insert into recipes (user_id, title, time_label, ingredients, instructions, image, kcal, protein, fat, carbs)
select * from (values
  (null::text, 'Томатный суп', '30 мин', 'помидор, лук, морковь, масло', 'Обжарьте лук и морковь, добавьте томаты, тушите 20 минут, пробейте блендером.', '/images/tomato-soup.jpg', 150, 3, 5, 22),
  (null, 'Крем-суп с зеленью', '25 мин', 'молоко, картофель, зелень, масло', 'Отварите картофель, добавьте молоко и зелень, взбейте до крема.', '/images/soup-cup.jpg', 210, 6, 11, 22),
  (null, 'Песто из зелени', '10 мин', 'зелень, масло, чеснок, сыр', 'Смешайте зелень, чеснок, сыр и масло в блендере.', '/images/green-spoon.jpg', 180, 4, 17, 3),
  (null, 'Шакшука', '20 мин', 'помидор, яйца, перец, специи', 'Тушите томаты с перцем, вбейте яйца и доведите до готовности.', '/images/shakshuka.jpg', 260, 14, 16, 12),
  (null, 'Простой салат', '10 мин', 'помидор, зелень, яйца, лимон', 'Нарежьте всё, заправьте лимоном и маслом.', '/images/fridge.jpg', 190, 9, 12, 10),
  (null, 'Омлет с зеленью', '12 мин', 'яйца, молоко, зелень, масло', 'Взбейте яйца с молоком и большим количеством мелко нарезанной зелени, затем обжарьте на среднем огне или запеките до готовности, нарежьте на порционные квадраты и подавайте со свежими огурцами.', '/images/omlet.jpg', 240, 16, 18, 4),
  (null, 'Курица с рисом', '45 мин', 'курица, рис, масло, специи', 'Обжарьте курицу, отварите рис, смешайте со специями.', '/images/chicken.jpg', 420, 32, 12, 45),
  (null, 'Овощное рагу', '40 мин', 'картофель, морковь, лук, перец, помидор', 'Тушите овощи под крышкой до мягкости.', '/images/ragu.jpg', 180, 4, 6, 28),
  (null, 'Блины на молоке', '25 мин', 'молоко, яйца, мука, сахар', 'Замесите жидкое тесто и жарьте тонкие блины.', '/images/blin.jpg', 220, 7, 8, 30),
  (null, 'Гречка с грибами', '30 мин', 'гречка, грибы, лук, масло', 'Отварите гречку, обжарьте грибы с луком, соедините.', '/images/grechka.jpg', 310, 11, 9, 46),
  (null, 'Паста с сыром', '20 мин', 'макароны, сыр, масло, чеснок', 'Отварите пасту, смешайте с маслом, чесноком и сыром.', '/images/pasta.jpg', 380, 14, 16, 46),
  (null, 'Творожная запеканка', '40 мин', 'творог, яйца, сахар, манка', 'Смешайте всё, выпекайте 30 минут при 180°.', '/images/zapekanka.jpg', 270, 18, 10, 24),
  (null, 'Рыба с лимоном', '25 мин', 'рыба, лимон, зелень, масло', 'Запеките рыбу с лимоном и зеленью 20 минут.', '/images/fish.jpg', 290, 28, 16, 2),
  (null, 'Чечевичный суп', '35 мин', 'чечевица, морковь, лук, специи', 'Отварите чечевицу с овощами до мягкости.', '/images/cheche.jpg', 230, 13, 3, 36),
  (null, 'Овсяная каша', '10 мин', 'овсянка, молоко, яблоко, мёд', 'Сварите овсянку на молоке, добавьте яблоко и мёд.', '/images/kasha.jpg', 280, 9, 7, 46),
  (null, 'Яичница с помидорами', '10 мин', 'яйца, помидор, масло, зелень', 'Обжарьте томаты, влейте яйца, посыпьте зеленью.', '/images/eggs.jpg', 250, 14, 19, 6),
  (null, 'Сэндвич с индейкой, авокадо и томатами', '5 мин', 'хлеб, соус, помидор, индейка, авокадо', 'Поджарьте два ломтика цельнозернового хлеба, смажьте горчицей, затем выложите слоями листья салата, тонкие ломтики индейки, кольца помидора, пластины авокадо и накройте вторым хлебом.', '/images/bread.jpg', 330, 14, 16, 32),
  (null, 'Борщ упрощённый', '50 мин', 'свекла, капуста, картофель, морковь, лук', 'Сварите овощи, добавьте свеклу в конце.', '/images/borsh.jpg', 160, 5, 4, 26)
) as v(user_id, title, time_label, ingredients, instructions, image, kcal, protein, fat, carbs)
